<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
$rows = [];
$total = 0;
$dbOnline = false;
$error = null;
try {
    $pdo = database();
    $rows = $pdo->query('SELECT id, water_level_cm, distance_cm, temperature_c, humidity_pct, rain_detected, alert_level, recorded_at FROM sensor_readings ORDER BY recorded_at DESC, id DESC LIMIT 50')->fetchAll();
    $total = (int)$pdo->query('SELECT COUNT(*) FROM sensor_readings')->fetchColumn();
    $dbOnline = true;
} catch (Throwable $exception) {
    error_log('Flood monitor climate page unavailable: ' . $exception->getMessage());
    $error = 'MySQL is unavailable. Start MySQL and import ../database/schema.sql to view climate records.';
}
$latest = $rows[0] ?? null;
$latestId = $latest ? (int)$latest['id'] : 0;
$latestFresh = $latest && abs(time() - (new DateTimeImmutable((string)$latest['recorded_at']))->getTimestamp()) <= 10;
$h = static fn (mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$fmt = static fn (mixed $value, int $digits = 1): string => is_numeric($value) ? number_format((float)$value, $digits) : '&mdash;';
?>
