<section class="climate-log-card"><div class="climate-log-heading"><div><div class="section-title-row"><span class="table-title-icon" aria-hidden="true">&#9719;</span><h2>Live climate records</h2><span class="count-pill" id="climateCount"><?= number_format($total) ?></span></div><p class="section-description">Newest readings appear automatically with their recorded time.</p></div><div class="log-refresh"><span class="live-dot"></span><span>Checking every second</span></div></div><div class="table-scroll"><table><thead><tr><th>RECORDED AT</th><th>WATER LEVEL</th><th>DISTANCE</th><th>TEMPERATURE</th><th>HUMIDITY</th><th>RAIN</th><th>ALERT</th></tr></thead><tbody id="climateRows">
<?php foreach ($rows as $row): $date = new DateTimeImmutable((string)$row['recorded_at']); $alert = in_array($row['alert_level'], ['normal','watch','warning','danger'], true) ? $row['alert_level'] : 'normal'; ?><tr><td class="timestamp-cell"><span class="row-led <?= $alert === 'danger' ? 'row-led-danger' : ($alert === 'warning' ? 'row-led-warning' : '') ?>"></span><span><?= $h($date->format('M j, Y')) ?></span><span class="timestamp-time"><?= $h($date->format('H:i:s')) ?></span></td><td><strong class="table-water-value"><?= $fmt($row['water_level_cm']) ?><span> cm</span></strong></td><td><?= $fmt($row['distance_cm']) ?><span class="unit-label"> cm</span></td><td><?= $fmt($row['temperature_c']) ?><span class="unit-label"> &deg;C</span></td><td><?= $fmt($row['humidity_pct'], 0) ?><span class="unit-label">%</span></td><td><span class="table-rain <?= !empty($row['rain_detected']) ? 'rain-active' : '' ?>"><span class="rain-led"></span><?= !empty($row['rain_detected']) ? 'Detected' : 'None' ?></span></td><td><span class="status-pill status-<?= $alert ?>"><span></span><?= ucfirst($alert) ?></span></td></tr><?php endforeach; ?>
